import type {
  ForbiddenSignal,
  VideoAnalysisQualityFixture,
} from '@/lib/video-analysis/quality-evaluation';

const UNIVERSAL_FORBIDDEN_SIGNALS: ForbiddenSignal[] = [
  {
    id: 'no-invented-retention',
    reason: 'Aucune courbe de rétention plateforme n’est fournie par cette fixture synthétique.',
    patterns: [
      '(?:la|ta|votre) rétention (?:chute|baisse|s’effondre)',
      'les spectateurs (?:quittent|abandonnent)',
      'taux de complétion (?:de|:) \\d',
    ],
  },
  {
    id: 'no-invented-platform-metrics',
    reason: 'Aucun export de vues, likes, commentaires ou partages n’est attaché.',
    patterns: [
      '\\d+(?:[.,]\\d+)? ?(?:vues|likes|commentaires|partages)',
      '\\d+(?:[.,]\\d+)? ?% d[’\']engagement',
    ],
  },
];

type FixtureInput = Omit<
  VideoAnalysisQualityFixture,
  'source' | 'usageAuthorization' | 'measuredSignals' | 'forbiddenSignals'
> & {
  forbiddenSignals?: ForbiddenSignal[];
};

function fixture(input: FixtureInput): VideoAnalysisQualityFixture {
  return {
    ...input,
    source: 'synthetic_qa_fixture',
    usageAuthorization: 'synthetic_no_personal_data',
    measuredSignals: {
      retention: false,
      platformMetrics: false,
    },
    forbiddenSignals: [
      ...UNIVERSAL_FORBIDDEN_SIGNALS,
      ...(input.forbiddenSignals ?? []),
    ],
  };
}

